function downloads(){return `<div class="download-panel"><div><strong>把完整学习手册带走</strong><p>正文、算例、论文卡片、全部面试题与自测答案。可离线阅读、检索和打印。</p></div><div class="download-actions"><a class="button primary" href="downloads/memory-architecture-handbook.pdf" download>下载 PDF 手册 ↓</a><a class="button" href="downloads/memory-architecture-handbook.html" download>下载离线 HTML ↓</a></div></div>`;}
function home(){const next=D.modules.find(m=>!state.done.includes(m.id))||D.modules[0];return `<section class="hero"><div><div class="eyebrow">从系统架构，深入存储芯片</div><h1>读懂一颗存储芯片<br><span>也能讲清每一次取舍</span></h1><p>从 DRAM 电荷与感放，到 HBM、HBF 和数字／模拟 CIM。用可追溯论文、可调参数实验和面试追问，把熟悉的 GPU 架构连接到存储内部。</p><div class="hero-actions"><a class="button primary" href="#/lesson/${next.id}">${state.done.length?'继续学习':'开始学习'} →</a><a class="button secondary" href="#/map">展开知识树</a></div></div><div class="hero-diagram">${heroSvg()}<small style="display:block;text-align:center;color:#8fa6c4;font-size:10px">学习关系示意 · 实际互连与控制器取决于具体产品</small></div></section><div class="stats"><div class="stat"><b>${D.modules.length}</b><span>循序渐进学习模块</span></div><div class="stat"><b>${D.papers.length}</b><span>论文与技术案例精读</span></div><div class="stat"><b>${D.sources.length}</b><span>可追溯一手资料</span></div><div class="stat"><b>${allQuiz.length+allInterview.length}</b><span>面试问答与自测题</span></div></div><div class="section-head"><h2>按你的节奏进入</h2><p>先掌握核心，再拓展研究边界</p></div><div class="route-grid">${Object.entries(paths).map(([id,p],i)=>`<article class="route-card"><span class="badge ${['','blue','violet'][i]}">${p.tag}</span><h3>${p.name}</h3><p>${p.intro}</p><a class="button" href="#/path/${id}">查看学习路线 →</a></article>`).join('')}</div><div class="section-head"><h2>知识之间，连起来学</h2><a href="#/map">完整知识树 ↗</a></div>${tree()}${downloads()}<div class="section-head"><h2>不要背结论，练习判断</h2></div><div class="route-grid"><article class="route-card"><span class="badge">DRAM</span><h3>为什么行命中更快？</h3><p>从电荷分享、感放恢复到 ACT / READ / PRE。亲自切换行命中、关闭行和行冲突。</p><a href="#/lab/timing">打开时序实验 →</a></article><article class="route-card"><span class="badge amber">HBF</span><h3>高带宽能抵消高延迟吗？</h3><p>调整页大小、并发量和有效数据比例，看带宽时延积与读放大如何限制收益。</p><a href="#/lab/hbf">打开 HBF 实验 →</a></article><article class="route-card"><span class="badge violet">CIM</span><h3>为什么还不能只等材料？</h3><p>观察量化、噪声和外围开销。区分器件、阵列、电路和完整系统的瓶颈。</p><a href="#/lab/cim">打开 CIM 实验 →</a></article></div>`;}
function pathPage(id){const p=paths[id]||paths.three;return `<div class="page-intro"><div class="eyebrow">学习路线 / ${p.tag}</div><h1>${p.name}</h1><p>${p.intro}</p></div><div class="checklist"><strong>每章学习顺序：</strong>先用自己的话回答“解决什么问题”，再走一遍算例，最后遮住答案口述面试题。遇到不熟悉的术语可使用顶部搜索。</div><ol class="path-list">${p.ids.filter(id=>byId[id]).map(id=>{const m=byId[id];return `<li><div><h3><a href="#/lesson/${m.id}">${esc(m.title)} ${state.done.includes(m.id)?'✓':''}</a></h3><p>${esc(m.intro)}</p><div class="subtle-label">${m.minutes} 分钟建议精读 · ${m.sections.length} 个小节</div></div></li>`;}).join('')}</ol>${downloads()}`;}
