function quizHtml(q){const a=state.answers[q.key],answered=Number.isInteger(a),correct=a===q.correct;return `<article class="quiz-card" data-quiz="${esc(q.key)}"><div class="eyebrow">${esc(q.module?.title||'本章自测')}</div><h3>${esc(q.q)}</h3><div class="quiz-options">${q.options.map((o,i)=>`<button class="quiz-option ${answered&&i===q.correct?'correct':''} ${answered&&i===a&&!correct?'incorrect':''}" data-choice="${i}" ${answered?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${esc(o)}</button>`).join('')}</div><div class="quiz-explanation">${answered?`<strong>${correct?'回答正确':'这题需要再想一层'}。</strong>${esc(q.explanation)} <button class="pill" data-retry="${esc(q.key)}">重新作答</button>`:''}</div></article>`;}
function lesson(id,section){const m=byId[id];if(!m)return '<div class="empty">没有找到这个模块。<a href="#/home">回到学习总览</a></div>';const i=D.modules.indexOf(m),g=groups.find(g=>g.id===m.group),sources=m.sourceIds.map(id=>bySource[id]).filter(Boolean);const quickLab=({'dram-cell':'cell','dram-timing':'timing','gpu-memory':'roofline','architecture-case':'capacity','hbf':'hbf','hbf-system':'hbf','cim-digital':'digital','cim-analog':'cim','cim-materials':'amdahl'})[id];return `<div class="lesson-layout"><article class="lesson-body"><div class="lesson-meta"><span class="badge ${g?.color||''}">${g?.label||''}</span><span>模块 ${String(i+1).padStart(2,'0')} / ${D.modules.length}</span><span>建议精读 ${m.minutes} 分钟</span><span>${m.level==='advanced'?'深入研读':'核心必会'}</span></div><h1>${esc(m.title)}</h1><p class="intro">${esc(m.intro)}</p>${m.prerequisites?.filter(p=>byId[p]).length?`<div class="reading-link">建议先学：${m.prerequisites.filter(p=>byId[p]).map(p=>`<a href="#/lesson/${p}">${esc(byId[p].title)}</a>`).join(' · ')}</div>`:''}<div class="lesson-outcomes"><h3>学完这一章，你应该能够</h3><ul>${m.outcomes.map(o=>`<li>${esc(o)}</li>`).join('')}</ul></div>${quickLab?`<a class="button" href="#/lab/${quickLab}">先用交互实验建立直觉 ↗</a>`:''}${m.sections.map((s,n)=>`<section class="lesson-section" id="sec-${esc(s.id)}"><div class="eyebrow">${String(n+1).padStart(2,'0')} / ${m.sections.length}</div><h2>${esc(s.title)}</h2>${s.html}</section>`).join('')}<section class="lesson-section" id="sec-interview"><h2>面试中如何说清楚</h2><p class="muted">先独立口述，再展开参考回答。参考回答是知识表达示例，不代表你已完成相关项目。</p>${m.interview.map(q=>`<details class="interview-item"><summary>${esc(q.q)}</summary><div class="answer">${esc(q.answer).replace(/\n/g,'<br>')}</div>${q.followups?.length?`<div class="followups"><strong>继续追问：</strong><ul>${q.followups.map(f=>`<li>${esc(f)}</li>`).join('')}</ul></div>`:''}</details>`).join('')}</section><section class="lesson-section" id="sec-quiz"><h2>检查你是否真的理解</h2>${m.quiz.map((q,n)=>quizHtml({...q,key:`${id}:${n}`,module:m})).join('')}</section><section class="lesson-section" id="sec-sources"><h2>论文与原始资料</h2><ul class="source-list">${sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><div class="source-meta">${s.year||''} · ${esc(s.venue||s.type)} · ${esc(s.evidence||'')}</div></li>`).join('')}</ul></section><section class="lesson-section" id="sec-notes"><h2>用自己的话记下来</h2><p class="muted">建议写下一个因果链、一处设计取舍，以及一个仍需确认的假设。自动保存在当前浏览器。</p><textarea class="note-area" data-note="${id}" aria-label="本章学习笔记" placeholder="例如：位线越长 → 电容越大 → 感测信号更小／恢复更慢；但感放开销可以摊薄……">${esc(state.notes[id]||'')}</textarea></section><button class="button primary" data-complete="${id}">${state.done.includes(id)?'✓ 已完成 · 点击撤销':'标记本章已完成'}</button><nav class="lesson-bottom">${i>0?`<a class="button" href="#/lesson/${D.modules[i-1].id}">← ${esc(D.modules[i-1].title)}</a>`:'<a class="button" href="#/map">← 知识树</a>'}${i<D.modules.length-1?`<a class="button" href="#/lesson/${D.modules[i+1].id}">${esc(D.modules[i+1].title)} →</a>`:'<a class="button" href="#/practice">进入模拟面试 →</a>'}</nav></article><aside class="lesson-aside"><h3>本章导航</h3><nav class="toc">${m.sections.map(s=>`<a href="#/lesson/${id}/${s.id}">${esc(s.title)}</a>`).join('')}<a href="#/lesson/${id}/interview">面试问答</a><a href="#/lesson/${id}/quiz">本章自测</a><a href="#/lesson/${id}/sources">原始资料</a><a href="#/lesson/${id}/notes">我的笔记</a></nav><button class="button" data-complete="${id}">${state.done.includes(id)?'✓ 已完成 · 点击撤销':'标记本章已完成'}</button><button class="button" data-bookmark="${id}">${state.bookmarks.includes(id)?'★ 已收藏':'☆ 收藏本章'}</button><div class="aside-block"><h3>阅读提示</h3><p>公式先检查单位，性能先问基线，论文结论先看实验边界。</p><p>教学算例不是器件规格；模拟结果不是量产实测。</p></div></aside></div>`;}
function notesPage(){const notes=Object.entries(state.notes).filter(([id,t])=>byId[id]&&t.trim());return `<div class="page-intro"><div class="eyebrow">个人学习空间</div><h1>我的笔记与进度</h1><p>记录你自己的因果链与设计判断。数据仅保存在当前浏览器；更换设备前，可以导出 JSON 备份再导入。</p></div><div class="toolbar"><button class="button primary" id="export-progress">导出笔记与进度 ↓</button><button class="button" id="import-progress">导入备份</button><input type="file" id="import-file" accept="application/json,.json" hidden><span class="muted">${state.done.length} 章已完成 · ${notes.length} 篇笔记</span></div><div class="section-head"><h2>收藏的模块</h2></div><div class="pills">${state.bookmarks.filter(id=>byId[id]).map(id=>`<a class="pill" href="#/lesson/${id}">${esc(byId[id].title)}</a>`).join('')||'<span class="muted">在学习页面点击“收藏本章”。</span>'}</div><div class="section-head"><h2>学习笔记</h2></div>${notes.length?notes.map(([id,t])=>`<article class="paper-card" style="margin-bottom:16px"><h3><a href="#/lesson/${id}/notes">${esc(byId[id].title)}</a></h3><p style="white-space:pre-wrap">${esc(t)}</p></article>`).join(''):'<div class="empty">从任意模块底部的笔记框开始，写下一次真正理解的瞬间。</div>'}${downloads()}`;}
function openSearch(){const d=$('#search-dialog');if(!d.open)d.showModal();$('#global-search').focus();search('');}
function search(query){const q=query.trim().toLowerCase();let items=[];if(q){for(const m of D.modules){if((m.title+' '+m.intro).toLowerCase().includes(q))items.push({url:`#/lesson/${m.id}`,title:m.title,text:m.intro,type:'模块'});for(const s of m.sections){const text=strip(s.html);const index=(s.title+' '+text).toLowerCase().indexOf(q);if(index>=0)items.push({url:`#/lesson/${m.id}/${s.id}`,title:s.title,text:text.slice(Math.max(0,text.toLowerCase().indexOf(q)-35),Math.max(0,text.toLowerCase().indexOf(q)-35)+125),type:m.title});}for(const x of m.interview)if((x.q+' '+x.answer).toLowerCase().includes(q))items.push({url:`#/lesson/${m.id}/interview`,title:x.q,text:x.answer.slice(0,110),type:'面试题'});}for(const p of D.papers)if((p.title+' '+p.problem+' '+p.mechanism).toLowerCase().includes(q))items.push({url:'#/papers',title:p.title,text:p.problem,type:'论文'});}else items=D.modules.slice(0,5).map(m=>({url:`#/lesson/${m.id}`,title:m.title,text:m.intro,type:'推荐起点'}));$('#search-results').innerHTML=items.slice(0,45).map(x=>`<a class="search-result" href="${x.url}"><span class="badge">${esc(x.type)}</span> ${esc(x.title)}<small>${esc(x.text)}</small></a>`).join('')||'<div class="empty">没有找到匹配内容，试试英文缩写或相关术语。</div>';}
// Remaining views and event wiring are appended below.
function papersPage(){const shown=D.papers.filter(p=>paperFilter==='all'||p.modules?.some(id=>byId[id]?.group===paperFilter));return `<div class="page-intro"><div class="eyebrow">从论文中学习架构判断</div><h1>论文精读库</h1><p>每张卡片都按“问题 → 机制 → 代价 → 证据边界”拆解。先理解作者改变了哪条数据路径，再判断收益是否适用于你的工作负载。勾选最多三篇，可并排比较。</p></div><div class="toolbar"><div class="pills">${[{id:'all',label:'全部'},...groups].map(g=>`<button class="pill ${paperFilter===g.id?'active':''}" data-paper-filter="${g.id}">${g.label}</button>`).join('')}</div><span class="practice-count">${shown.length} 篇</span></div><div id="paper-comparison"></div><div class="paper-grid">${shown.map(p=>`<article class="paper-card"><span class="badge">${esc(p.venue||'研究论文')} · ${p.year||''}</span><h3>${esc(p.title)}</h3><p><strong>解决什么：</strong>${esc(p.problem)}</p><p><strong>如何做到：</strong>${esc(p.mechanism)}</p><details><summary>展开取舍与证据边界</summary><p><strong>代价与限制：</strong>${esc(p.tradeoff)}</p><p><strong>证据：</strong>${esc(p.evidence)}</p><p><strong>面试复述：</strong>${esc(p.interview)}</p>${p.modules?.filter(id=>byId[id]).map(id=>`<div class="reading-link"><a href="#/lesson/${id}">结合 ${esc(byId[id].title)} 学习 →</a></div>`).join('')||''}</details><div class="paper-footer"><a href="${esc(p.url)}" target="_blank" rel="noopener">阅读原文 ↗</a><label><input type="checkbox" data-compare="${esc(p.id)}" ${compared.has(p.id)?'checked':''}>加入比较</label></div></article>`).join('')}</div><div class="section-head"><h2>完整来源索引</h2><p>论文、厂商规格和标准资料均可追溯</p></div><ul class="source-list">${D.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><div class="source-meta">${s.year||''} · ${esc(s.venue||s.type)} · ${esc(s.evidence)}</div></li>`).join('')}</ul>`;}
function paperComparison(){const p=D.papers.filter(p=>compared.has(p.id));const target=$('#paper-comparison');if(!target)return;target.innerHTML=p.length?`<div class="comparison"><table><thead><tr><th>比较维度</th>${p.map(x=>`<th>${esc(x.title)}</th>`).join('')}</tr></thead><tbody>${[['问题','problem'],['核心机制','mechanism'],['付出的代价','tradeoff'],['证据边界','evidence']].map(([label,key])=>`<tr><th>${label}</th>${p.map(x=>`<td>${esc(x[key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'';}
function practicePage(){let list=allQuiz.filter(q=>currentQuizFilter==='all'||currentQuizFilter==='wrong'&&Number.isInteger(state.answers[q.key])&&state.answers[q.key]!==q.correct||q.module.group===currentQuizFilter);const answered=allQuiz.filter(q=>Number.isInteger(state.answers[q.key])),correct=answered.filter(q=>state.answers[q.key]===q.correct);return `<div class="page-intro"><div class="eyebrow">把理解变成可表达的判断</div><h1>面试与自测</h1><p>先说结论，再说明机制、定量依据和适用边界。对于项目经验，明确区分阅读、复现、设计与流片；这里的案例不能代替你真实做过的工作。</p></div><div class="toolbar"><div class="pills"><button class="pill ${practiceMode==='quiz'?'active':''}" data-practice-mode="quiz">知识自测 · ${allQuiz.length} 题</button><button class="pill ${practiceMode==='interview'?'active':''}" data-practice-mode="interview">口述面试 · ${allInterview.length} 题</button></div><span class="practice-count" id="quiz-score">已答 ${answered.length} 题 · 答对 ${correct.length} 题</span></div><div class="pills">${[{id:'all',label:'全部'},...groups,{id:'wrong',label:'错题回顾'}].filter(g=>practiceMode==='quiz'||g.id!=='wrong').map(g=>`<button class="pill ${currentQuizFilter===g.id?'active':''}" data-quiz-filter="${g.id}">${g.label}</button>`).join('')}</div>${practiceMode==='quiz'?`<div style="margin-top:20px">${list.length?list.map(quizHtml).join(''):'<div class="empty">这里还没有题目。完成自测后，答错的题会自动进入错题回顾。</div>'}</div>`:interviewPanel()}`;}
function updateQuizScore(){const target=$('#quiz-score');if(target){const answered=allQuiz.filter(q=>Number.isInteger(state.answers[q.key]));target.textContent=`已答 ${answered.length} 题 · 答对 ${answered.filter(q=>state.answers[q.key]===q.correct).length} 题`;}}
function interviewPanel(){let list=allInterview.filter(q=>currentQuizFilter==='all'||q.module.group===currentQuizFilter);if(!list.length)list=allInterview;interviewIndex=((interviewIndex%list.length)+list.length)%list.length;const q=list[interviewIndex];return `<article class="quiz-card"><div class="eyebrow">${esc(q.module.title)} · ${interviewIndex+1} / ${list.length}</div><h3>${esc(q.q)}</h3><p class="muted">给自己 60–90 秒：画出数据路径，列出关键约束，再给出判断。</p><textarea class="note-area practice-answer" aria-label="本次面试回答草稿" placeholder="先独立组织回答，再展开下面的参考答案。"></textarea><details class="interview-item"><summary>展开参考回答与追问</summary><div class="answer">${esc(q.answer).replace(/\n/g,'<br>')}</div><ul class="followups">${(q.followups||[]).map(f=>`<li>${esc(f)}</li>`).join('')}</ul><a class="reading-link" href="#/lesson/${q.module.id}/interview">回到对应知识模块 →</a></details><div class="toolbar"><button class="button" data-interview-step="-1">← 上一题</button><button class="button primary" data-interview-step="1">下一题 →</button><button class="button" id="random-interview">随机抽题</button></div></article>`;}
const glossary=[
 ['Cell','存储单元','DRAM 常用 1T1C：访问晶体管控制连接，电容保存电荷。不要把整个 Bank 当成一个单元。','dram-cell'],
 ['Wordline / Bitline','字线与位线','字线选择一排单元；位线传递很小的电荷变化到感应放大器。','dram-cell'],
 ['Sense amplifier','感应放大器','识别位线微小电压差并再生为完整逻辑电平，同时向已连接的单元恢复电荷。','dram-cell'],
 ['Row buffer','行缓冲','DRAM 中保持当前行数据的感放集合；不是额外放在芯片外的一块 SRAM。','dram-map'],
 ['Subarray / Mat','子阵列与阵列块','芯片内部为缩短线路、复用外围电路而划分的物理组织；术语及边界依实现而异。','dram-array'],
 ['Bank / Bank group','存储体与存储体组','提供内部并行性；同组和跨组命令可能受不同的间隔约束。不能只数 Bank 来推算带宽。','dram-timing'],
 ['Rank / Channel','Rank 与通道','Rank 是协同响应命令的一组芯片；Channel 是一组接口资源。增加 Rank 不一定增加总线宽度。','dram-map'],
 ['ACT / PRE / REF','激活 预充电 刷新','ACT 打开行并触发感测恢复；PRE 关闭行并均衡位线；REF 维护数据保持。','dram-timing'],
 ['tRCD / tRP / tRAS','关键 DRAM 时序','分别约束激活到列访问、预充电到下次激活、激活到允许预充电的最小间隔。','dram-timing'],
 ['tRRD / tFAW','激活速率约束','限制 Bank 间激活密度以控制瞬时电流等风险；并行 Bank 再多也不能无限同时 ACT。','dram-timing'],
 ['Prefetch','预取架构','DRAM 的 n-prefetch 是阵列与外部高速 I/O 间的数据宽度转换；不同于 CPU 对未来地址的预测预取。','dram-array'],
 ['FR-FCFS','就绪优先调度','优先服务准备好的命令和行命中，提高吞吐，但要防止其他请求长期饥饿。','controller'],
 ['PHY / DFI','物理层与控制器接口','PHY 负责电气与时序收发，并参与链路训练；DFI 规范控制器与 PHY 的协作接口。','controller'],
 ['MLP / BLP','访存并行与 Bank 并行','MLP 关注同时在途的访存；BLP 关注多个 Bank 的重叠工作。两者不等价。','gpu-memory'],
 ['Coalescing','GPU 合并访问','把线程的地址请求合并成较少的内存事务；它优化请求流量，不直接保证 DRAM 行命中。','gpu-memory'],
 ['Roofline / Arithmetic intensity','屋顶线与算术强度','以实际跨某层边界的数据字节数为分母计算运算强度，再比较算力和带宽上限。','gpu-memory'],
 ['HBM / TSV / Base die','高带宽内存与堆叠','HBM 使用 DRAM 芯片堆叠和宽接口；TSV 是贯穿硅的连接，底层逻辑职责随产品而异。','hbm'],
 ['HBF','高带宽闪存','基于 NAND 的新存储层，试图用并行和互连提高吞吐。不能由高带宽推导出 DRAM 式低延迟与写能力。','hbf'],
 ['Page / Block / Plane','NAND 页 块 平面','读取与编程以页等粒度组织，擦除按块进行；多个 Plane 和 Die 提供并行性。','nand'],
 ['FTL / GC / WAF','闪存管理与写放大','FTL 管理地址映射，GC 回收空间。WAF=实际 NAND 写入字节／主机逻辑写入字节；无额外写入时为 1。','nand'],
 ['KV cache / GQA','注意力缓存与分组查询','KV 保存历史 token 的键和值；GQA 共享 KV 头，容量公式应使用 KV 头数。','architecture-case'],
 ['TPOT / TTFT','每 token 时间与首 token 时间','分别反映生成阶段单步响应与首个输出等待；吞吐提升不保证单请求体验改善。','hbf-system'],
 ['PIM / CIM','近存与存内计算','命名在文献中并不完全统一；先说明计算发生的位置、使用的物理机制和接口。','pim'],
 ['DCIM / ACIM','数字与模拟 CIM','数字路径用逻辑门、加法树等求值；模拟路径用电流、电荷或时间承载计算量。存储介质与计算域是两条不同分类轴。','cim-digital'],
 ['ADC / DAC','模数与数模转换','把模拟量转换成数字码或反向转换。转换精度、速度、能量及共享比例会限制 CIM 宏性能。','cim-analog'],
 ['Bit slicing / Bit serial','位切片与位串行','将高精度权重分散到多个低精度单元，或分多周期输入不同位，之后按位权累加。','cim-digital'],
 ['IR drop / Sneak path','压降与旁路电流','互连电阻改变实际读电压；未选择路径可能贡献额外电流。选择器能缓解部分问题，却有面积成本。','cim-analog'],
 ['RRAM / PCM / FeFET','新型非易失介质','分别涉及阻变、相变和铁电控制阈值等机制。每种路线都要同时检查一致性、保持性、寿命和集成条件。','cim-materials'],
 ['Retention / Endurance','保持性与耐久性','保持性描述多长时间不丢信息；耐久性描述可承受多少次写入或切换。不能相互代替。','cim-materials'],
 ['ENOB / TOPS/W','有效位数与能效','接口位宽不等于有效计算精度；TOPS/W 比较需对齐运算定义、精度、稀疏度、利用率和统计边界。','cim-hybrid'],
 ['On-die ECC','片内纠错','通常保护片内特定数据路径，不能自动覆盖芯片引脚、封装、总线及系统端到端故障。','dram-tradeoffs'],
 ['RowHammer / RowPress','访问扰动问题','重复激活与长时间保持行开启都可能产生扰动；需结合器件、访问模式与缓解方案分析。','dram-refresh']
];
function glossaryPage(){return `<div class="page-intro"><div class="eyebrow">把缩写变成清楚的结构</div><h1>术语速查</h1><p>这些解释用来建立第一层直觉。点击对应模块，继续看机制、适用条件和反例。</p></div><div class="toolbar"><input type="search" id="glossary-search" placeholder="筛选中文或英文术语" aria-label="筛选术语"></div><div class="glossary-grid">${glossary.map(([en,cn,text,id])=>`<article class="term-card" data-term="${esc((en+' '+cn+' '+text).toLowerCase())}"><span class="eyebrow">${esc(en)}</span><h3>${cn}</h3><p>${text}</p><a class="reading-link" href="#/lesson/${id}">深入学习 →</a></article>`).join('')}</div>`;}
const labInfo={cell:['电荷分享','从 1T1C 看感放为什么必要'],timing:['DRAM 时序','把行命中、关闭行和冲突画出来'],roofline:['Roofline','区分带宽上限与计算上限'],capacity:['权重与 KV','估算模型容量预算'],hbf:['HBF 并发','高带宽需要多少在途请求'],cim:['CIM 精度','看看量化和误差怎样进入点积'],amdahl:['系统瓶颈','阵列再快也受外围约束']};
let labValues={cell:{vdd:1.1,cell:20,bitline:200,bit:1},timing:{cl:14,rcd:14,rp:14,mode:'conflict'},roofline:{peak:400,bw:2,ai:32},capacity:{params:70,bits:4,layers:80,kvHeads:8,headDim:128,seq:32768,batch:1,kvBytes:2},hbf:{peak:1,latency:20,pageKiB:16,concurrency:1024,usefulKiB:4},cim:{x0:8,x1:4,x2:12,x3:2,bits:6,noise:2},amdahl:{share:20,speedup:10}};
function slider(key,label,min,max,step,unit=''){return `<label class="control"><span class="control-header"><span>${label}</span><output id="out-${key}">${fmt(labValues[labTab][key],3)} ${unit}</output></span><input type="range" min="${min}" max="${max}" step="${step}" value="${labValues[labTab][key]}" data-lab-input="${key}" data-unit="${unit}" aria-label="${label}"></label>`;}
function select(key,label,options){return `<label class="control"><span class="control-header">${label}</span><select data-lab-input="${key}" aria-label="${label}">${options.map(([v,l])=>`<option value="${v}" ${String(labValues[labTab][key])===String(v)?'selected':''}>${l}</option>`).join('')}</select></label>`;}
function labPage(id){if(id&&labInfo[id])labTab=id;let controls='';if(labTab==='cell')controls=select('bit','存储的逻辑值',[[1,'1 · 充电'],[0,'0 · 放电']])+slider('vdd','电源电压',.6,1.5,.05,'V')+slider('cell','单元电容',5,50,5,'fF')+slider('bitline','位线电容',50,500,25,'fF');if(labTab==='timing')controls=select('mode','访问状态',[['hit','行命中：目标行已就绪'],['closed','关闭行：从 ACT 开始'],['conflict','行冲突：旧行可立即 PRE']])+slider('cl','READ 到首数据',5,40,1,'ns')+slider('rcd','tRCD',5,40,1,'ns')+slider('rp','tRP',5,40,1,'ns');if(labTab==='roofline')controls=slider('peak','峰值计算吞吐',10,1000,10,'TFLOP/s')+slider('bw','可用内存带宽',.1,8,.1,'TB/s')+slider('ai','算术强度',1,512,1,'FLOP/B');if(labTab==='capacity')controls=slider('params','模型参数量',1,405,1,'B 参数')+select('bits','权重位宽',[[2,'2 bit'],[4,'4 bit'],[8,'8 bit'],[16,'16 bit']])+slider('layers','层数',1,128,1)+select('kvHeads','KV 头数',[[1,'1'],[4,'4'],[8,'8'],[16,'16'],[32,'32'],[64,'64']])+select('headDim','每个头维度',[[64,'64'],[128,'128'],[256,'256']])+select('seq','上下文 token 数',[[2048,'2K'],[8192,'8K'],[32768,'32K'],[131072,'128K']])+slider('batch','并发序列数',1,64,1)+select('kvBytes','每个 KV 元素字节数',[[1,'1 B'],[2,'2 B'],[4,'4 B']]);if(labTab==='hbf')controls=slider('peak','接口峰值带宽',.1,3,.1,'TB/s')+slider('latency','有效读取延迟',1,100,1,'μs')+select('pageKiB','每请求传输粒度',[[4,'4 KiB'],[16,'16 KiB'],[64,'64 KiB']])+slider('concurrency','独立在途请求数',1,4096,1)+select('usefulKiB','每请求有用数据',[[1,'1 KiB'],[4,'4 KiB'],[16,'16 KiB'],[64,'64 KiB']]);if(labTab==='cim')controls=[0,1,2,3].map(i=>slider('x'+i,`输入 x${i}`,0,15,1)).join('')+slider('bits','输出量化码宽',2,10,1,'bit')+slider('noise','扰动幅度占正满量程 F',0,15,.5,'%');if(labTab==='amdahl')controls=slider('share','可优化阵列占总能量',0,100,1,'%')+slider('speedup','阵列能量改善倍数',1,100,1,'倍');return `<div class="page-intro"><div class="eyebrow">可调参数 · 看见因果关系</div><h1>交互实验室</h1><p>所有参数都是教学假设，模型用于推导数量级和观察趋势，不代替器件 SPICE、协议仿真或芯片实测。</p></div><div class="pills lab-tabs">${Object.entries(labInfo).map(([id,[name]])=>`<a class="pill ${id===labTab?'active':''}" href="#/lab/${id}">${name}</a>`).join('')}</div><div class="lab-grid"><section class="lab-controls"><h3>调整参数</h3>${controls}<button class="button" id="lab-reset">恢复本实验默认值</button></section><section class="lab-visual"><div class="eyebrow">${labInfo[labTab][0]}</div><h3>${labInfo[labTab][1]}</h3><div id="lab-output"></div></section></div>`;}
labInfo.digital=['数字 CIM 位乘','从 AND 部分积到精确多位乘法'];
